CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT 'Family member', avatar text NOT NULL DEFAULT '🌱', preferences jsonb NOT NULL DEFAULT '{}'); GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_family_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name) VALUES(new.id,coalesce(new.raw_user_meta_data->>'name','Family member')); RETURN new; END $$; CREATE TRIGGER family_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_family_profile();
CREATE TABLE public.households(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, code text NOT NULL UNIQUE DEFAULT upper(substr(encode(gen_random_bytes(8),'hex'),1,6)), state jsonb NOT NULL DEFAULT '{"chores":[],"goals":[],"ledger":[],"notifications":[]}', version integer NOT NULL DEFAULT 0); GRANT SELECT ON public.households TO authenticated; GRANT ALL ON public.households TO service_role; ALTER TABLE public.households ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('primary_parent','co_parent','child')), UNIQUE(user_id)); GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.family_member(h uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM user_roles WHERE household_id=h AND user_id=auth.uid()) $$; CREATE POLICY family_read ON public.households FOR SELECT TO authenticated USING(public.family_member(id)); CREATE POLICY family_roles ON public.user_roles FOR SELECT TO authenticated USING(public.family_member(household_id)); CREATE POLICY family_profiles ON public.profiles FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM user_roles r WHERE r.user_id=profiles.id AND public.family_member(r.household_id)));
CREATE TABLE public.family_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id), code text UNIQUE NOT NULL DEFAULT upper(substr(encode(gen_random_bytes(8),'hex'),1,6)), role text NOT NULL CHECK(role IN('child','co_parent')), email text, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days'); GRANT SELECT ON public.family_invites TO authenticated; GRANT ALL ON public.family_invites TO service_role; ALTER TABLE public.family_invites ENABLE ROW LEVEL SECURITY; CREATE POLICY parent_invites ON public.family_invites FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM user_roles WHERE user_id=auth.uid() AND household_id=family_invites.household_id AND role<>'child'));
CREATE TABLE public.push_devices(user_id uuid NOT NULL, token text PRIMARY KEY); GRANT SELECT,INSERT,UPDATE,DELETE ON public.push_devices TO authenticated; GRANT ALL ON public.push_devices TO service_role; ALTER TABLE public.push_devices ENABLE ROW LEVEL SECURITY; CREATE POLICY own_device ON public.push_devices FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.family_setup(family_name text DEFAULT NULL, join_code text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h uuid; r text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF EXISTS(SELECT 1 FROM user_roles WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Already in a family'; END IF; IF join_code IS NOT NULL THEN SELECT household_id,role INTO h,r FROM family_invites WHERE code=upper(join_code) AND expires_at>now() AND (email IS NULL OR lower(email)=lower(auth.jwt()->>'email')); IF h IS NULL THEN SELECT id,'child' INTO h,r FROM households WHERE code=upper(join_code); END IF; IF h IS NULL THEN RAISE EXCEPTION 'Invalid or expired family code'; END IF; ELSE IF length(trim(family_name))<2 THEN RAISE EXCEPTION 'Enter a family name'; END IF; INSERT INTO households(name) VALUES(trim(family_name)) RETURNING id INTO h; r:='primary_parent'; END IF; INSERT INTO user_roles(user_id,household_id,role) VALUES(auth.uid(),h,r); RETURN h; END $$;
CREATE FUNCTION public.family_invite(invite_role text, invite_email text DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h uuid; c text; BEGIN SELECT household_id INTO h FROM user_roles WHERE user_id=auth.uid() AND role<>'child'; IF h IS NULL OR invite_role NOT IN('child','co_parent') THEN RAISE EXCEPTION 'Parent access required'; END IF; INSERT INTO family_invites(household_id,role,email) VALUES(h,invite_role,nullif(trim(invite_email),'')) RETURNING code INTO c; RETURN c; END $$;
CREATE FUNCTION public.family_action(action text, payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h uuid; r text; s jsonb; c jsonb; item jsonb; arr jsonb; uid text:=auth.uid()::text; target text; amount integer; BEGIN SELECT household_id,role INTO h,r FROM user_roles WHERE user_id=auth.uid(); IF h IS NULL THEN RAISE EXCEPTION 'Join a family first'; END IF; SELECT state INTO s FROM households WHERE id=h FOR UPDATE; IF action='create_chore' THEN IF r='child' THEN RAISE EXCEPTION 'Parent access required'; END IF; IF NOT EXISTS(SELECT 1 FROM user_roles WHERE household_id=h AND user_id=(payload->>'childId')::uuid AND role='child') THEN RAISE EXCEPTION 'Choose a child in your family'; END IF; amount:=(payload->>'value')::int; IF amount<0 OR amount>100000 OR (payload->>'day')::int NOT BETWEEN 0 AND 6 OR length(trim(payload->>'title'))<1 THEN RAISE EXCEPTION 'Invalid chore'; END IF; item:=payload||jsonb_build_object('id',gen_random_uuid(),'status','todo'); s:=jsonb_set(s,'{chores}',(s->'chores')||jsonb_build_array(item));
ELSIF action IN('complete','approve','reject') THEN SELECT x INTO c FROM jsonb_array_elements(s->'chores') x WHERE x->>'id'=payload->>'id'; IF c IS NULL THEN RAISE EXCEPTION 'Chore not found'; END IF; IF action='complete' THEN IF c->>'childId'<>uid OR r<>'child' OR c->>'status' NOT IN('todo','rejected') THEN RAISE EXCEPTION 'Only the assigned child can submit this chore'; END IF; c:=c||jsonb_build_object('status','pending','proof',payload->>'proof','submittedAt',now()); ELSE IF r='child' OR c->>'status'<>'pending' THEN RAISE EXCEPTION 'Parent approval required'; END IF; IF action='approve' THEN c:=c||jsonb_build_object('status','approved'); s:=jsonb_set(s,'{ledger}',(s->'ledger')||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'childId',c->>'childId','title',c->>'title','amount',(c->>'value')::int,'type','earning','date',now()))); ELSE c:=c||jsonb_build_object('status','rejected','note',payload->>'note'); END IF; END IF; SELECT coalesce(jsonb_agg(CASE WHEN x->>'id'=c->>'id' THEN c ELSE x END),'[]') INTO arr FROM jsonb_array_elements(s->'chores') x; s:=jsonb_set(s,'{chores}',arr); s:=jsonb_set(s,'{notifications}',(s->'notifications')||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'title',c->>'title','message',CASE action WHEN 'complete' THEN 'Ready for parent approval' WHEN 'approve' THEN 'Approved — pocket money earned!' ELSE 'Needs another try: '||coalesce(payload->>'note','') END,'childId',c->>'childId','date',now())));
ELSIF action='pay' THEN IF r='child' THEN RAISE EXCEPTION 'Parent access required'; END IF; target:=payload->>'childId'; IF NOT EXISTS(SELECT 1 FROM user_roles WHERE household_id=h AND user_id=target::uuid AND role='child') THEN RAISE EXCEPTION 'Child not found'; END IF; SELECT coalesce(sum((x->>'amount')::int),0) INTO amount FROM jsonb_array_elements(s->'ledger') x WHERE x->>'childId'=target; IF amount<=0 THEN RAISE EXCEPTION 'Nothing to pay'; END IF; s:=jsonb_set(s,'{ledger}',(s->'ledger')||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'childId',target,'title','Pocket money paid','amount',-amount,'type','payment','date',now())));
ELSIF action='goal' THEN IF r<>'child' OR (payload->>'target')::int<=0 THEN RAISE EXCEPTION 'Children can create a savings goal'; END IF; s:=jsonb_set(s,'{goals}',(s->'goals')||jsonb_build_array(payload||jsonb_build_object('id',gen_random_uuid(),'childId',uid,'saved',0)));
ELSIF action='allocate' THEN SELECT x INTO c FROM jsonb_array_elements(s->'goals') x WHERE x->>'id'=payload->>'id' AND x->>'childId'=uid; IF c IS NULL OR r<>'child' THEN RAISE EXCEPTION 'Goal not found'; END IF; amount:=(payload->>'amount')::int; SELECT coalesce(sum((x->>'amount')::int),0) INTO target FROM jsonb_array_elements(s->'ledger') x WHERE x->>'childId'=uid; IF amount<=0 OR amount>target::int THEN RAISE EXCEPTION 'Not enough pocket money'; END IF; SELECT coalesce(sum((x->>'saved')::int),0) INTO target FROM jsonb_array_elements(s->'goals') x WHERE x->>'childId'=uid; IF amount+target::int>(SELECT coalesce(sum((x->>'amount')::int),0) FROM jsonb_array_elements(s->'ledger') x WHERE x->>'childId'=uid) THEN RAISE EXCEPTION 'This money is already allocated'; END IF; c:=c||jsonb_build_object('saved',least((c->>'target')::int,(c->>'saved')::int+amount)); SELECT jsonb_agg(CASE WHEN x->>'id'=c->>'id' THEN c ELSE x END) INTO arr FROM jsonb_array_elements(s->'goals') x; s:=jsonb_set(s,'{goals}',arr);
ELSE RAISE EXCEPTION 'Unknown action'; END IF; UPDATE households SET state=s,version=version+1 WHERE id=h; RETURN s; END $$;
REVOKE ALL ON FUNCTION public.family_setup(text,text),public.family_invite(text,text),public.family_action(text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.family_setup(text,text),public.family_invite(text,text),public.family_action(text,jsonb) TO authenticated;
CREATE POLICY proof_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='chore-proof' AND (storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY proof_family_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='chore-proof' AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id::text=(storage.foldername(name))[1] AND public.family_member(r.household_id)));